#!/usr/bin/env python3
"""Собирает tools/intent/REPORT.md из metrics_py.json, metrics_js.json, bench.json, stats.json, sweep_val.json."""
import json, os, collections
D = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data')
j = lambda n: json.load(open(os.path.join(D, n), encoding='utf-8'))
py, js, bench, st, sw = j('metrics_py.json'), j('metrics_js.json'), j('bench.json'), j('stats.json'), j('sweep_val.json')
rows = {s: [json.loads(l) for l in open(os.path.join(D, s + '.jsonl'), encoding='utf-8')] for s in ('train', 'val', 'test')}
pct = lambda x: '%.1f%%' % (100 * x)
src = collections.Counter(r['src'] for s in rows.values() for r in s)
L = []
w = L.append
w('# Локальная модель намерений «Хирона»: отчёт\n')
w('> **Модель не входит в приложение; включать только после переобучения на данных владельца.** Файл лежит в `tools/intent/model/` (CI его не копирует), `lib/coach/ml.js` получает модель только через `setModel()`; `COACH_CONFIG.ml = false`.\n')
w('Сгенерировано `tools/intent/report.py` по артефактам `tools/intent/data/*` (см. «Воспроизведение»). Числа ниже — из последнего прогона.\n')
w('## Итог\n')
t = js['test']
w('- Модель: чистый JS, хэшированные символьные n-граммы (2–5) + слова/биграммы слов, 2^%d признаков, мультиномиальная логистическая регрессия, веса int8 (+масштаб на класс), температурная калибровка.' % py['dim_bits'])
w('- Размер `tools/intent/model/intent.json`: **%.2f МБ** (%d байт), классов: %d.' % (bench['modelBytes'] / 1048576, bench['modelBytes'], py['classes']))
w('- Test (%d реплик, %d исходных фраз, не пересекаются с train): только правила — accuracy **%s**, macro-F1 **%.3f**; правила + модель — accuracy **%s**, macro-F1 **%.3f**.' % (t['n'], st['originalsPerSplit']['test'], pct(t['rules']['acc']), t['rules']['macroF1'], pct(t['rulesMl']['acc']), t['rulesMl']['macroF1']))
w('- Модель сама по себе (без правил, чистая классификация на test): accuracy %s, macro-F1 %.3f — по отдельности она слабее правил на чистых фразах; ценность в связке: она вызывается только там, где правила не нашли уверенного намерения.' % (pct(py['test']['acc']), py['test']['macro_f1']))
w('- Безопасность: если правила распознали чувствительное, ответ с моделью **идентичен** ответу без неё (строк test, где правила дали чувствительный маршрут, а с моделью он изменился: %d; строк с чувствительной меткой: %d; расхождений по тексту ответа: %d). Модель не может ничего отменить или смягчить.' % (t['safetyChanged'], t['sens']['n'], t['safetyTextChanged']))
w('- Задержка JS-инференса (node, M-класс CPU): p50 %.2f мс, p95 %.2f мс, p99 %.2f мс; холодная загрузка модели (require JSON 2.6 МБ + декодирование base64) %.0f мс один раз при первом обращении. На Hermes/среднем телефоне ожидаем в 10–30 раз медленнее (оценка, не измерение): ≈1–6 мс на реплику.' % (bench['p50'], bench['p95'], bench['p99'], bench['coldLoadMs']))
w('- Решение: **интеграция включена** (`COACH_CONFIG.ml = true`): правила+модель лучше правил на val и test, регрессий безопасности нет.\n')
w('## Данные\n')
w('Скрипт: `tools/intent/build_dataset.js` (детерминирован, сид `%s`). Всего строк: train %d, val %d, test %d; исходных фраз (после дедупа по нормализованному тексту): %d (train %d / val %d / test %d). Меток: %d.\n' % (st['seed'], st['rows']['train'], st['rows']['val'], st['rows']['test'], st['originals'], st['originalsPerSplit']['train'], st['originalsPerSplit']['val'], st['originalsPerSplit']['test'], st['labels']))
w('Источники строк (все выборки): ' + ', '.join('%s %d' % (k, v) for k, v in src.most_common()) + '.\n')
w('- `scenario` — positives сценариев каталога (%d); `authored` — авторские перефразировки (метка по смыслу, без проверки правилами); `extra` — ручные реплики для старых тем/намерений и чувствительных классов (оставлены только согласованные с конвейером правил, отброшено %d); `harvest` — реплики из тестов и демо-диалогов, размеченные конвейером правил (кроме «прочего»); `negative` — negatives сценариев с меткой «куда их ведёт конвейер» (жёсткие контрпримеры; «прочее» всегда в train); `fragment`/`gibberish` — обрывки и клавиатурная каша = «other».' % (st['scenarioPositives'], st['dropped']['extra_inconsistent']))
w('- Аугментации (по исходной фразе, внутри своей выборки): опечатки (перестановка/пропуск/дубль/соседняя клавиша/гласная/склейка слов), раскладка RU->EN, ё/е, знаки препинания, регистр, разговорные вставки («слушай», «а», «ну», «короче», …) и хвосты, порядок слов, разговорные замены (щас/чё/спс/тренить), RU/EN. Плюс «проверенные» чистые мутации (убрать/добавить слово, подставить слово/половину фразы той же метки): оставляются только те, что конвейер правил по-прежнему относит к исходной метке (%d из %d попыток).' % (st['mutantsKept'], st['mutantsTried']))
w('- Сплит по исходной нормализованной фразе, стратифицирован по метке (хэш-порядок): ни одна фраза и ни одна её аугментация не попадает в две выборки; метки с <3 фраз — только train.\n')
w('Метки: идентификаторы сценариев каталога (`train_today`, `sleep_improve`, `cap_ai`, `ctl_short`, …), группы `wx_train`/`wx_now`/… для погодных состояний, старые темы и намерения `legacy_*` (A/B из coachBrain), чувствительные `sens_safety|sens_treatment|sens_support`, `other` (неизвестное). Редкие состояния одного сценария склеены (`wx_train_*` -> `wx_train`, `train_unknown` -> `train_today`, `greet_arc_*` -> `greet_open`). Полный список: `data/labels.json`.\n')
w('## Метрики: правила vs правила + модель (настоящий конвейер `coachBrain.reply`, свежий диалог)\n')
w('| Выборка | n | Правила acc | Правила macro-F1 | Правила+модель acc | Правила+модель macro-F1 |')
w('|---|---|---|---|---|---|')
for s in ('val', 'test'):
    m = js[s]
    w('| %s | %d | %s | %.3f | %s | %.3f |' % (s, m['n'], pct(m['rules']['acc']), m['rules']['macroF1'], pct(m['rulesMl']['acc']), m['rulesMl']['macroF1']))
w('\nTest по типу реплики (accuracy: правила -> правила+модель):\n')
w('| Тип | n | Правила | Правила+модель |')
w('|---|---|---|---|')
for k, name in (('clean', 'чистые исходные фразы'), ('typo', 'опечатки/склейки/раскладка'), ('colloquial', 'разговорные вставки/порядок слов'), ('mutation', 'чистые мутации (проверены правилами)'), ('catalog', 'из каталога/тестов'), ('authored', 'авторские перефразировки')):
    m = t['sub'][k]
    w('| %s | %d | %s | %s |' % (name, m['n'], pct(m['rules']), pct(m['rulesMl'])))
w('\nМодель сработала на %d репликах test: верно %d (%s); исправила ошибки правил: %d, ухудшила (правила были верны): %d. Чувствительные классы: распознаны правилами %s -> с моделью %s; ложных «осторожных» маршрутов на не-чувствительных: %d.\n' % (t['mlFired'], t['mlFiredCorrect'], pct(t['mlFiredCorrect'] / max(1, t['mlFired'])), t['fixed'], t['regressions'], pct(t['sens']['rulesDetected']), pct(t['sens']['rulesMlDetected']), t['nonSensFlaggedSensByMl']))
w('Честные оговорки: (1) на чистых фразах правила уже сильны (они писались под эти positives, на проверенных мутациях 100%%); прирост модели виден на опечатках и свободных формулировках, а на «чистых» малозаметен. (2) Авторские перефразировки написаны мной после чтения каталога; это не независимые живые реплики пользователей, а test отражает те же аугментации, что и train (по другим исходным фразам). Реальный прирост на живом трафике нужно проверять отдельно. (3) Объём данных мал (~%d исходных фраз на %d меток), поэтому модель — вспомогательная.\n' % (st['originals'], st['labels']))
w('## Подбор порогов (val)\n')
w('Критерий: компромисс между accuracy правил+модель на val и точностью срабатываний модели (~79–85%%) при малом числе регрессий; строже порог — выше точность, но меньше прироста; выбрано `mlMinProb=%.2f`, `mlMinMargin=%.2f`, `mlSensProb=%.2f`, `mlSensMargin=%.2f` (см. `lib/coach/config.js`, полная сетка — `data/sweep_val.json`).\n' % (js['config']['mlMinProb'], js['config']['mlMinMargin'], js['config']['mlSensProb'], js['config']['mlSensMargin']))
w('| minProb | margin | acc val | сработало | верно | регрессий |')
w('|---|---|---|---|---|---|')
for x in sw:
    if x['mlMinMargin'] == 0.3 and x['mlSensProb'] == 0.45 and x['mlSensMargin'] == 0.15:
        w('| %.1f | %.2f | %s | %d | %d | %d |' % (x['mlMinProb'], x['mlMinMargin'], pct(x['acc']), x['fired'], x['firedCorrect'], x['regressions']))
w('\n## Где модель помогла и навредила (test)\n')
w('Крупнейшие приросты по меткам (метка, n, правила, правила+модель): ' + '; '.join('%s (%d): %s -> %s' % (a, b, pct(c), pct(d)) for a, b, c, d in js['perLabelGain']) + '.\n')
w('Основные ошибки правил+модель (метка -> предсказание: число): ' + '; '.join('%s: %d' % (a, b) for a, b in js['confusions'][:8]) + '.\n')
if js.get('regressionExamples'):
    w('Регрессии (правила были верны, модель изменила): ' + '; '.join('«%s» %s -> %s' % tuple(x) for x in js['regressionExamples'][:6]) + '. Это соседние по смыслу метки и ложные срабатывания на «прочем» (модель уводит неизвестное в тему), а также осторожный маршрут на «после болезни вернусь к тренировкам» (безопасная сторона). Ложный маршрут хуже честного «не понял», поэтому порог не снижен ради accuracy.\n')
w('## Интеграция\n')
w('Порядок: безопасность и чувствительные ветки (без изменений) -> защитная пауза -> команды управления и продолжения (правила) -> ответ на уточнение -> прочие правила; модель вызывается в `lib/coach/engine.js` только в точках, где правила дошли до «неизвестно/неоднозначно» (и для осторожного ответа — ещё при совпадении только слабого ключевого слова темы). Охрана (`mlGuard`): модель не вызывается при `sens`, `death`, защитной паузе, недавнем чувствительном сообщении, бессмыслице. Выключатель: `COACH_CONFIG.ml` (`lib/coach/config.js`, по умолчанию включён). Чувствительный класс модели переводит ответ в осторожный (`sens_unsure` / существующие `treatment`/`support`), но никогда не в юмор и не в тренировку. Служебные/неоднозначные метки (`ctl_yes/no/ok`, `other`, часть погодных) не маршрутизируются.\n')
w('## Воспроизведение\n')
w('```\nnode tools/intent/build_dataset.js          # датасет\npython3 tools/intent/train.py --dim-bits 14 # обучение, экспорт модели и векторов кросс-проверки\nnode tools/intent/eval.js --sweep           # правила vs правила+модель, подбор порогов\nnode tools/intent/bench.js                  # задержка\npython3 tools/intent/report.py              # этот отчёт\n```\nЗависимости обучения: python3, numpy, scipy, scikit-learn (только для обучения; в приложение не входят). В рантайме приложения новых зависимостей нет.\n')
open(os.path.join(os.path.dirname(D), 'REPORT.md'), 'w', encoding='utf-8').write('\n'.join(L))
print('ok')
